/** Compare both intercept modes using factories generated by the Python sample.
 */
#include "../../least_squares_intercept_with_intercept.hpp"
#include "../../least_squares_intercept_without_intercept.hpp"

#include <iostream>
#include <stdexcept>

namespace {
void expect_near(double actual, double expected) {
  const double difference = actual - expected;
  if (!(difference >= -1.0e-5 && difference <= 1.0e-5)) {
    throw std::runtime_error("Least-squares intercept sample failed");
  }
}
} // namespace

int main() {
  using WithIntercept = least_squares_intercept_with_intercept::type;
  using WithoutIntercept = least_squares_intercept_without_intercept::type;
  static_assert(WithIntercept::FIT_INTERCEPT, "Expected affine regression");
  static_assert(!WithoutIntercept::FIT_INTERCEPT, "Expected linear regression");
  static_assert(WithIntercept::PARAMETER_COUNT == 2, "Slope and intercept");
  static_assert(WithoutIntercept::PARAMETER_COUNT == 1, "Slope only");

  WithIntercept::X_Type X;
  WithIntercept::Y_Type y;
  for (std::size_t i = 0; i < X.ROWS; ++i) {
    X(i, 0) = static_cast<double>(i + 1);
    y(i, 0) = static_cast<double>(i + 2);
  }
  auto affine = least_squares_intercept_with_intercept::make();
  auto linear = least_squares_intercept_without_intercept::make();
  affine.fit(X, y);
  linear.fit(X, y);
  const auto affine_weights = affine.get_weights();
  const auto linear_weights = linear.get_weights();
  expect_near(affine_weights(0, 0), 1.0);
  expect_near(affine_weights(1, 0), 1.0);
  expect_near(linear_weights(0, 0), 10.0 / 7.0);

  const auto affine_prediction = affine.predict(X);
  const auto linear_prediction = linear.predict(X);
  WithIntercept::X_Type zero;
  const auto zero_prediction = linear.predict(zero);
  for (std::size_t i = 0; i < X.ROWS; ++i) {
    expect_near(affine_prediction(i, 0), y(i, 0));
    expect_near(linear_prediction(i, 0), X(i, 0) * 10.0 / 7.0);
    expect_near(zero_prediction(i, 0), 0.0);
  }
  std::cout << "With intercept: slope=" << affine_weights(0, 0)
            << ", intercept=" << affine_weights(1, 0) << '\n';
  std::cout << "Without intercept: slope=" << linear_weights(0, 0) << '\n';

  return 0;
}
